def make_grid(seed):
 import random
 flat=[8,7,7,2,7,5,6,3,4]
 rng=random.Random(seed)
 blocks=[]
 for _ in range(3):
  a=flat.copy(); rng.shuffle(a); blocks.append([a[i:i+3] for i in range(0,9,3)])
 out=[]
 for r in range(3): out.append([8,7,7,2,7,5,6,3,4][r*3:r*3+3]+[blocks[0][r][c] for c in range(3)])
 for r in range(3): out.append(blocks[1][r]+blocks[2][r])
 return out,blocks
make_grid(0)

def make_np_grid(seed, kind='default'):
 import numpy as np
 rng=np.random.default_rng(seed) if kind=='default' else np.random.RandomState(seed)
 flat=np.array([8,7,7,2,7,5,6,3,4])
 blocks=[]
 for _ in range(3):
  a=flat.copy(); rng.shuffle(a); blocks.append(a.reshape(3,3).tolist())
 out=[]
 for r in range(3): out.append([8,7,7][0:3]+blocks[0][r])
 for r in range(3): out.append(blocks[1][r]+blocks[2][r])
 return out,blocks
make_np_grid(42,'default')
